# WAR INTEL — Layer 1: wallet performance observations (Alpha Memory foundation)
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-intel-layer1.ps1
$ErrorActionPreference = 'Stop'
Write-Host 'Installing WAR INTEL layer 1 (Alpha Memory)...' -ForegroundColor Cyan
if (-not (Test-Path 'migrations')) { New-Item -ItemType Directory -Force -Path 'migrations' | Out-Null }
if (-not (Test-Path 'src\product\intel')) { New-Item -ItemType Directory -Force -Path 'src\product\intel' | Out-Null }
if (-not (Test-Path 'src\product\persistence\pg')) { New-Item -ItemType Directory -Force -Path 'src\product\persistence\pg' | Out-Null }

# ---- migrations/0008_wallet_perf.sql ----
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'migrations\0008_wallet_perf.sql'), [Convert]::FromBase64String($b64))
Write-Host '  wrote migrations/0008_wallet_perf.sql' -ForegroundColor Green

# ---- src/product/intel/perfObservationStore.ts ----
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'src\product\intel\perfObservationStore.ts'), [Convert]::FromBase64String($b64))
Write-Host '  wrote src/product/intel/perfObservationStore.ts' -ForegroundColor Green

# ---- src/product/persistence/pg/pgPerfObservationStore.ts ----
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'src\product\persistence\pg\pgPerfObservationStore.ts'), [Convert]::FromBase64String($b64))
Write-Host '  wrote src/product/persistence/pg/pgPerfObservationStore.ts' -ForegroundColor Green

Write-Host 'Done. Run:  npm run build; npm test' -ForegroundColor Cyan